/* ============================================================================
 * Helper: Construct pointer arrays from strided data
 * ========================================================================= */

/**
 * @brief Construct array of pointers from strided data
 *
 * Given a base pointer, element stride, and count, creates an array of
 * pointers pointing to each strided element.
 *
 * @param base_ptr Base pointer to data
 * @param stride Byte stride between elements
 * @param count Number of pointers to create
 * @return Allocated array of pointers (must be freed with fb_free_temp_buffer)
 */
static void **fb_construct_strided_ptr_array(const void *base_ptr,
                                             size_t stride, size_t count) {
  void **ptr_array = (void **)fb_allocate_temp_buffer(count * sizeof(void *));
  if (!ptr_array) {
    return NULL;
  }

  for (size_t i = 0; i < count; i++) {
    ptr_array[i] = (void *)((uintptr_t)base_ptr + i * stride);
  }

  return ptr_array;
}

/* ============================================================================
 * GEMM: Strided Batched from Array Batched (SGEMM)
 * ========================================================================= */

void fb_sgemm_batch_strided_from_sgemm_batch(
    const fb_layout_t layout, const fb_transpose_t transa,
    const fb_transpose_t transb, const int64_t m, const int64_t n,
    const int64_t k, const float alpha, const float *A, const int64_t lda,
    const int64_t strideA, const float *B, const int64_t ldb,
    const int64_t strideB, const float beta, float *C, const int64_t ldc,
    const int64_t strideC, const int64_t batch_count) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->sgemm_batch) {
    return;
  }

  /* Construct pointer arrays from strided data */
  const float **A_array =
      (const float **)fb_construct_strided_ptr_array(A, strideA, batch_count);
  const float **B_array =
      (const float **)fb_construct_strided_ptr_array(B, strideB, batch_count);
  float **C_array =
      (float **)fb_construct_strided_ptr_array(C, strideC, batch_count);

  if (!A_array || !B_array || !C_array) {
    /* Cleanup and return on allocation failure */
    fb_free_temp_buffer(A_array);
    fb_free_temp_buffer(B_array);
    fb_free_temp_buffer(C_array);
    return;
  }

  /* Call array-based operation */
  vtable->sgemm_batch(layout, transa, transb, m, n, k, alpha, A_array, lda,
                      B_array, ldb, beta, C_array, ldc, batch_count);

  /* Cleanup */
  fb_free_temp_buffer(A_array);
  fb_free_temp_buffer(B_array);
  fb_free_temp_buffer(C_array);
}

