/**
 * @brief Install strided batched GEMM wrappers from array-based variants
 *
 * @param vtable Vtable to fill
 */
void fb_autofill_gemm_batch_strided_from_gemm_batch(
    fb_backend_vtable_t *vtable) {
  if (!vtable) {
    return;
  }

  if (vtable->sgemm_batch_strided == NULL && vtable->sgemm_batch != NULL) {
    vtable->sgemm_batch_strided = fb_sgemm_batch_strided_from_sgemm_batch;
  }

  if (vtable->dgemm_batch_strided == NULL && vtable->dgemm_batch != NULL) {
    vtable->dgemm_batch_strided = fb_dgemm_batch_strided_from_dgemm_batch;
  }

  if (vtable->cgemm_batch_strided == NULL && vtable->cgemm_batch != NULL) {
    vtable->cgemm_batch_strided = fb_cgemm_batch_strided_from_cgemm_batch;
  }

  if (vtable->zgemm_batch_strided == NULL && vtable->zgemm_batch != NULL) {
    vtable->zgemm_batch_strided = fb_zgemm_batch_strided_from_zgemm_batch;
  }
}

